#include <bits/stdc++.h>
using namespace std;

int64_t count_inversions(const vector<int>& arr) {
    int n = arr.size();
    int64_t inv = 0;
    vector<int> temp(n);
    function<void(int,int)> merge_sort = [&](int l, int r) {
        if (l >= r) return;
        int mid = (l + r) / 2;
        merge_sort(l, mid);
        merge_sort(mid+1, r);
        int i = l, j = mid+1, k = l;
        while (i <= mid && j <= r) {
            if (arr[i] <= arr[j]) {
                temp[k++] = arr[i++];
            } else {
                temp[k++] = arr[j++];
                inv += (mid - i + 1);
            }
        }
        while (i <= mid) temp[k++] = arr[i++];
        while (j <= r) temp[k++] = arr[j++];
        for (int p = l; p <= r; p++) arr[p] = temp[p];
    };
    vector<int> copy = arr;
    merge_sort(0, n-1);
    return inv;
}

