#include <bits/stdc++.h>
using namespace std;

struct BIT {
    int n;
    vector<int> bit;
    BIT(int n = 0) { init(n); }
    void init(int n_) {
        n = n_;
        bit.assign(n + 1, 0);
    }
    void add(int idx, int val) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += val;
    }
    int sumPrefix(int idx) const {
        int r = 0;
        for (; idx > 0; idx -= idx & -idx) r += bit[idx];
        return r;
    }
    int rangeSum(int l, int r) const {
        if (l > r) return 0;
        return sumPrefix(r) - sumPrefix(l - 1);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<char> color(2 * N + 1);
    vector<int> num(2 * N + 1);

    vector<int> posW(N + 1), posB(N + 1);

    for (int i = 1; i <= 2 * N; ++i) {
        char c;
        int x;
        cin >> c >> x;
        color[i] = c;
        num[i] = x;
        if (c == 'W') posW[x] = i;
        else posB[x] = i;
    }

    // costW[i][j]:
    // when i whites and j blacks have already been taken,
    // cost to take white ball i+1 next.
    // Similarly for costB.
    vector<vector<int>> costW(N + 1, vector<int>(N + 1, 0));
    vector<vector<int>> costB(N + 1, vector<int>(N + 1, 0));

    // Compute costW
    {
        BIT fw(2 * N), fb(2 * N);
        for (int i = 0; i <= N; ++i) {
            fw.init(2 * N);
            fb.init(2 * N);
            for (int k = 1; k <= i; ++k) fw.add(posW[k], 1);
            for (int j = 0; j <= N; ++j) {
                if (i < N) {
                    int p = posW[i + 1];
                    int removedBefore = fw.sumPrefix(p) + fb.sumPrefix(p);
                    costW[i][j] = (p - 1) - removedBefore;
                }
                if (j < N) fb.add(posB[j + 1], 1);
            }
        }
    }

    // Compute costB
    {
        BIT fw(2 * N), fb(2 * N);
        for (int j = 0; j <= N; ++j) {
            fw.init(2 * N);
            fb.init(2 * N);
            for (int k = 1; k <= j; ++k) fb.add(posB[k], 1);
            for (int i = 0; i <= N; ++i) {
                if (j < N) {
                    int p = posB[j + 1];
                    int removedBefore = fw.sumPrefix(p) + fb.sumPrefix(p);
                    costB[i][j] = (p - 1) - removedBefore;
                }
                if (i < N) fw.add(posW[i + 1], 1);
            }
        }
    }

    const long long INF = (1LL << 60);
    vector<vector<long long>> dp(N + 1, vector<long long>(N + 1, INF));
    dp[0][0] = 0;

    for (int i = 0; i <= N; ++i) {
        for (int j = 0; j <= N; ++j) {
            if (dp[i][j] == INF) continue;
            if (i < N) {
                dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + costW[i][j]);
            }
            if (j < N) {
                dp[i][j + 1] = min(dp[i][j + 1], dp[i][j] + costB[i][j]);
            }
        }
    }

    cout << dp[N][N] << '\n';
    return 0;
}

