#define MAXN 200005

typedef struct {
    int value;
    int color; // 0 for white, 1 for black
    int idx;   // original index
} Ball;

Ball balls[MAXN];
int pos[MAXN]; // position in target sequence
int bit[MAXN];
int N;

void update(int idx, int val) {
    while (idx <= 2 * N) {
        bit[idx] += val;
        idx += idx & -idx;
    }
}

int query(int idx) {
    int sum = 0;
    while (idx > 0) {
        sum += bit[idx];
        idx -= idx & -idx;
    }
    return sum;
}

long long count_inversions(int order) {
    // order = 0: white then black for each number
    // order = 1: black then white for each number
    int target_pos = 1;
    int white_pos[N+1], black_pos[N+1];
    for (int i = 1; i <= N; i++) {
        if (order == 0) {
            white_pos[i] = target_pos++;
            black_pos[i] = target_pos++;
        } else {
            black_pos[i] = target_pos++;
            white_pos[i] = target_pos++;
        }
    }

    for (int i = 0; i < 2 * N; i++) {
        if (balls[i].color == 0) {
            pos[i] = white_pos[balls[i].value];
        } else {
            pos[i] = black_pos[balls[i].value];
        }
    }

    memset(bit, 0, sizeof(bit));
    long long inversions = 0;
    for (int i = 0; i < 2 * N; i++) {
        inversions += (i - query(pos[i]));
        update(pos[i], 1);
    }
    return inversions;
}

