long long merge_count(int *arr, int *tmp, int l, int r) {
    if (r - l <= 1) return 0;
    int m = (l + r) / 2;
    long long cnt = merge_count(arr, tmp, l, m) + merge_count(arr, tmp, m, r);
    int i = l, j = m, k = l;
    while (i < m && j < r) {
        if (arr[i] <= arr[j]) tmp[k++] = arr[i++];
        else { tmp[k++] = arr[j++]; cnt += m - i; }
    }
    while (i < m) tmp[k++] = arr[i++];
    while (j < r) tmp[k++] = arr[j++];
    for (int x = l; x < r; x++) arr[x] = tmp[x];
    return cnt;
}

