    long long fixed = merge_count(wa,tmp,0,N) + merge_count(ba,tmp,0,N);
    // DP to find min cross inversions
    // dp[i][j] = min cross inv using first i white and j black balls
    long long **dp = malloc((N+1)*sizeof(long long*));
    for(int i=0;i<=N;i++){dp[i]=malloc((N+1)*sizeof(long long));for(int j=0;j<=N;j++)dp[i][j]=1e18;}
    dp[0][0]=0;
    for(int i=0;i<=N;i++) for(int j=0;j<=N;j++){
        if(dp[i][j]==1e18) continue;
        if(i<N){ // place white ball i next
            // cross inv: number of black balls already placed (j) that come after wp[i] in original
            // black balls placed are b[0..j-1], their positions are bp[0..j-1]
            // count how many bp[k] > wp[i] for k in 0..j-1
            // precompute? 
            long long cross=0;
            for(int k=0;k<j;k++) if(bp[k]>wp[i]) cross++;
            if(dp[i+1][j]>dp[i][j]+cross) dp[i+1][j]=dp[i][j]+cross;
        }
