} Ball;

typedef struct {
    int n;
    int *bit;
} Fenwick;

static void bit_init(Fenwick *fw, int n) {
    fw->n = n;
    fw->bit = (int*)calloc(n + 2, sizeof(int));
}

static void bit_add(Fenwick *fw, int idx, int val) {
    for (; idx <= fw->n; idx += idx & -idx) fw->bit[idx] += val;
}

static int bit_sum(Fenwick *fw, int idx) {
    int s = 0;
    for (; idx > 0; idx -= idx & -idx) s += fw->bit[idx];
    return s;
}

static void bit_free(Fenwick *fw) {
    free(fw->bit);
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int M = 2 * N;
    Ball *a = (Ball*)malloc(sizeof(Ball) * (M + 1));

    int *posW = (int*)malloc(sizeof(int) * (N + 1));
    int *posB = (int*)malloc(sizeof(int) * (N + 1));

    for (int i = 1; i <= M; i++) {
        char s[8];
        int x;
        scanf("%s %d", s, &x);
        a[i].c = s[0];
        a[i].x = x;
        if (a[i].c == 'W') posW[x] = i;
        else posB[x] = i;
    }

    /*
      DP[i][j]:
      minimum swaps after already taking
      white 1..i and black 1..j into the final sequence.
      Next chosen ball must be W(i+1) or B(j+1).

      Cost to take a ball at original position p:
      number of not-yet-taken balls before p
      = p - (# already taken before p)

      # already taken before p can be computed from counts of chosen whites/blacks
      whose original positions are < p.
    */

    int **cntW = (int**)malloc(sizeof(int*) * (N + 1));
    int **cntB = (int**)malloc(sizeof(int*) * (N + 1));
    for (int i = 0; i <= N; i++) {
        cntW[i] = (int*)calloc(N + 1, sizeof(int));
        cntB[i] = (int*)calloc(N + 1, sizeof(int));
    }

    // cntW[i][j] = among white 1..i, how many have position < posB[j] / used differently below
    // We build generic tables:
    // wBeforeW[i][k] = count of white 1..i with posW[t] < posW[k]
    // wBeforeB[i][k] = count of white 1..i with posW[t] < posB[k]
    // similarly for black.
    // To save memory, reuse cntW/cntB for one dimension and compute four tables.

    int **wBeforeW = (int**)malloc(sizeof(int*) * (N + 1));
    int **wBeforeB = (int**)malloc(sizeof(int*) * (N + 1));
    int **bBeforeW = (int**)malloc(sizeof(int*) * (N + 1));
    int **bBeforeB = (int**)malloc(sizeof(int*) * (N + 1));
    for (int i = 0; i <= N; i++) {
        wBeforeW[i] = (int*)calloc(N + 1, sizeof(int));
        wBeforeB[i] = (int*)calloc(N + 1, sizeof(int));
        bBeforeW[i] = (int*)calloc(N + 1, sizeof(int));
        bBeforeB[i] = (int*)calloc(N + 1, sizeof(int));
    }

    for (int i = 1; i <= N; i++) {
        for (int k = 1; k <= N; k++) {
            wBeforeW[i][k] = wBeforeW[i - 1][k] + (posW[i] < posW[k]);
            wBeforeB[i][k] = wBeforeB[i - 1][k] + (posW[i] < posB[k]);
            bBeforeW[i][k] = bBeforeW[i - 1][k] + (posB[i] < posW[k]);
            bBeforeB[i][k] = bBeforeB[i - 1][k] + (posB[i] < posB[k]);
        }
    }

    long long **dp = (long long**)malloc(sizeof(long long*) * (N + 1));
    for (int i = 0; i <= N; i++) {
        dp[i] = (long long*)malloc(sizeof(long long) * (N + 1));
        for (int j = 0; j <= N; j++) dp[i][j] = INF;
    }
    dp[0][0] = 0;

    for (int i = 0; i <= N; i++) {
        for (int j = 0; j <= N; j++) {
            if (dp[i][j] == INF) continue;

            if (i < N) {
                int k = i + 1;
                int p = posW[k];
                int takenBefore = wBeforeW[i][k] + bBeforeW[j][k];
                long long cost = (long long)p - 1 - takenBefore;
                if (dp[i + 1][j] > dp[i][j] + cost) {
                    dp[i + 1][j] = dp[i][j] + cost;
                }
            }

            if (j < N) {
                int k = j + 1;
                int p = posB[k];
                int takenBefore = wBeforeB[i][k] + bBeforeB[j][k];
                long long cost = (long long)p - 1 - takenBefore;
                if (dp[i][j + 1] > dp[i][j] + cost) {
                    dp[i][j + 1] = dp[i][j] + cost;
                }
            }
        }
    }

    printf("%lld\n", dp[N][N]);

    for (int i = 0; i <= N; i++) {
        free(wBeforeW[i]);
        free(wBeforeB[i]);
        free(bBeforeW[i]);
        free(bBeforeB[i]);
        free(dp[i]);
        free(cntW[i]);
        free(cntB[i]);
    }
    free(wBeforeW);
    free(wBeforeB);
    free(bBeforeW);
    free(bBeforeB);
    free(dp);
    free(cntW);
    free(cntB);
    free(a);
    free(posW);
    free(posB);

    return 0;
}

