            }
        }

        // Generate final target order: interleave white and black by value
        // We can choose interleaving order: all possibilities? Actually the minimum
        // is achieved by either white-first or black-first interleaving.
        long ans = Long.MAX_VALUE;

        // Try white first in final sequence (1W, 1B, 2W, 2B, ...)
        List<Integer> targetOrder = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            targetOrder.add(whitePos.get(i));
            targetOrder.add(blackPos.get(i));
        }
        ans = Math.min(ans, countInversions(targetOrder));

        // Try black first (1B, 1W, 2B, 2W, ...)
        targetOrder.clear();
        for (int i = 0; i < N; i++) {
            targetOrder.add(blackPos.get(i));
            targetOrder.add(whitePos.get(i));
        }
        ans = Math.min(ans, countInversions(targetOrder));

        System.out.println(ans);
    }

    // Count inversions in list of positions (minimum adjacent swaps to sort)
    static long countInversions(List<Integer> arr) {
        int n = arr.size();
        if (n <= 1) return 0;
        int mid = n / 2;
        List<Integer> left = new ArrayList<>(arr.subList(0, mid));
        List<Integer> right = new ArrayList<>(arr.subList(mid, n));
        long inv = countInversions(left) + countInversions(right);
        int i = 0, j = 0, k = 0;
        while (i < left.size() && j < right.size()) {
            if (left.get(i) <= right.get(j)) {
                arr.set(k++, left.get(i++));
            } else {
                arr.set(k++, right.get(j++));
                inv += left.size() - i;
            }
        }
        while (i < left.size()) arr.set(k++, left.get(i++));
        while (j < right.size()) arr.set(k++, right.get(j++));
        return inv;
    }
}

