public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            if (c == -1) return null;
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        int[] posW = new int[N + 1];
        int[] posB = new int[N + 1];

        // Input format: 2N balls, each as (color, number)
        // color is "W"/"B" or "White"/"Black" first letter enough.
        for (int i = 1; i <= 2 * N; i++) {
            String c = fs.next();
            int x = fs.nextInt();
            char ch = c.charAt(0);
            if (ch == 'W' || ch == 'w') posW[x] = i;
            else posB[x] = i;
        }

        // lessW[i][j] = number of white balls with label <= j that are before white i
        // but we only need counts by original positions:
        // prefW[k][p] = # of white balls with label <= k and position <= p
        // prefB similarly.
        int[][] prefW = new int[N + 1][2 * N + 1];
        int[][] prefB = new int[N + 1][2 * N + 1];

        for (int k = 1; k <= N; k++) {
            for (int p = 1; p <= 2 * N; p++) {
                prefW[k][p] = prefW[k - 1][p];
                prefB[k][p] = prefB[k - 1][p];
            }
            for (int p = 1; p <= 2 * N; p++) {
                prefW[k][p] += prefW[k][p - 1];
                prefB[k][p] += prefB[k][p - 1];
            }
            prefW[k][posW[k]]++;
            prefB[k][posB[k]]++;
            for (int p = posW[k]; p <= 2 * N; p++) prefW[k][p]++;
            for (int p = posB[k]; p <= 2 * N; p++) prefB[k][p]++;
        }

        // costW[i][j]:
        // if we have already taken white 1..i-1 and black 1..j,
        // cost to take white i next =
        // number of remaining balls before posW[i]
        // = posW[i]-1 - (#already removed before it)
        int[][] dp = new int[N + 1][N + 1];
        int INF = 1 << 29;
        for (int i = 0; i <= N; i++) Arrays.fill(dp[i], INF);
        dp[0][0] = 0;

        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= N; j++) {
                int cur = dp[i][j];
                if (cur == INF) continue;

                if (i < N) {
                    int p = posW[i + 1];
                    int removedBefore =
                            prefW[i][p] + prefB[j][p];
                    int cost = (p - 1) - removedBefore;
                    dp[i + 1][j] = Math.min(dp[i + 1][j], cur + cost);
                }

                if (j < N) {
                    int p = posB[j + 1];
                    int removedBefore =
                            prefW[i][p] + prefB[j][p];
                    int cost = (p - 1) - removedBefore;
                    dp[i][j + 1] = Math.min(dp[i][j + 1], cur + cost);
                }
            }
        }

        System.out.println(dp[N][N]);
    }
}
